// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address owner = c.owner();
        uint256 beforeOwner = owner.balance;
        uint256 beforeC = address(c).balance;

        vm.deal(address(this), 1 wei);
        vm.prank(address(this));
        c.go{value: 1 wei}();

        uint256 afterOwner = owner.balance;
        uint256 afterC = address(c).balance;

        // Reference: target call succeeds, balance transferred to owner
        // Bug: target call to address(0) fails, revert before transfer
        // So after the call, in the reference owner gets the wei, in bug it reverts
        assertTrue(afterOwner == beforeOwner + 1 wei);
    }
}

