// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Owner is the deployer (msg.sender). Record owner's initial balance.
        address owner = address(this);
        uint256 balanceBefore = owner.balance;

        // Owner calls go() with 1 wei
        vm.deal(owner, 1 ether);
        vm.prank(owner);
        c.go{value: 1}();

        // After the call, owner's balance should increase by 1 in the reference.
        bool ok = (owner.balance == balanceBefore + 1);
        assertTrue(ok);
    }
}
